// Normalize input from any channel into standard format
const input = $input.item.json;
let normalized = {
  channel: 'unknown',
  sender_id: null,
  sender_name: null,
  message_text: '',
  is_callback: false,
  callback_data: null,
  customer_id: null
};

// Telegram message
if (input.message?.text) {
  normalized.channel = 'telegram';
  normalized.sender_id = String(input.message.chat.id);
  normalized.sender_name = input.message.from?.first_name || 'Guest';
  normalized.message_text = input.message.text;
}
// Telegram callback
else if (input.callback_query) {
  normalized.channel = 'telegram';
  normalized.sender_id = String(input.callback_query.message.chat.id);
  normalized.sender_name = input.callback_query.from?.first_name || 'Guest';
  normalized.is_callback = true;
  normalized.callback_data = input.callback_query.data;
  normalized.message_text = input.callback_query.data;
}
// WhatsApp
else if (input.entry?.[0]?.changes?.[0]?.value?.messages?.[0]) {
  const msg = input.entry[0].changes[0].value.messages[0];
  const contact = input.entry[0].changes[0].value.contacts?.[0];
  normalized.channel = 'whatsapp';
  normalized.sender_id = msg.from;
  normalized.sender_name = contact?.profile?.name || 'Guest';
  normalized.message_text = msg.text?.body || msg.interactive?.button_reply?.title || '';
  normalized.is_callback = !!msg.interactive;
  normalized.callback_data = msg.interactive?.button_reply?.id || null;
}
// Twilio SMS
else if (input.Body && input.From) {
  normalized.channel = 'sms';
  normalized.sender_id = input.From;
  normalized.sender_name = 'Guest';
  normalized.message_text = input.Body;
}

normalized.timestamp = new Date().toISOString();
return normalized;

// Merge customer_id + property context + DATE CONTEXT
const normalized = $('Normalize Input').item.json;
const customerResult = $input.item.json;

const customerId = customerResult?.customer_id || '00000000-0000-0000-0000-000000000001';
const timezone = customerResult?.timezone || 'Asia/Manila';

const isOwner = (customerResult?.owner_telegram === normalized.sender_id) ||
                (customerResult?.owner_contact === normalized.sender_id);

// ══════ DATE CONTEXT ══════
const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const months = ['January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'];

const now = new Date();
const yyyy = now.getFullYear();
const mm = String(now.getMonth() + 1).padStart(2, '0');
const dd = String(now.getDate()).padStart(2, '0');
const today = yyyy + '-' + mm + '-' + dd;
const dayName = days[now.getDay()];
const monthName = months[now.getMonth()];

// Build 14-day calendar with clear day-date pairs
const calendarLines = [];
const dateMap = {}; // dayName -> first occurrence date string

for (let i = 0; i < 14; i++) {
  const d = new Date(now.getTime() + i * 86400000);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  const dateStr = y + '-' + m + '-' + day;
  const dn = days[d.getDay()];
  const mn = months[d.getMonth()];

  // Formatted as: "Thursday 2026-02-19 (February 19)"
  let label = '';
  if (i === 0) label = '  <-- TODAY';
  else if (i === 1) label = '  <-- TOMORROW';

  calendarLines.push(dn + ' ' + dateStr + ' (' + mn + ' ' + d.getDate() + ')' + label);

  // Track "next" occurrences of each day name (skip today)
  if (i > 0 && !dateMap[dn]) {
    dateMap[dn] = dn + ', ' + mn + ' ' + d.getDate() + ', ' + y + ' (' + dateStr + ')';
  }
}

const calendar = calendarLines.join('\n');
const todayFull = dayName + ', ' + monthName + ' ' + now.getDate() + ', ' + yyyy;

// Tomorrow convenience field
const tmrw = new Date(now.getTime() + 86400000);
const tmrwDay = days[tmrw.getDay()];
const tmrwMonth = months[tmrw.getMonth()];
const tmrwStr = tmrw.getFullYear() + '-' + String(tmrw.getMonth()+1).padStart(2,'0') + '-' + String(tmrw.getDate()).padStart(2,'0');
const tomorrowFull = tmrwDay + ', ' + tmrwMonth + ' ' + tmrw.getDate() + ', ' + tmrw.getFullYear() + ' (' + tmrwStr + ')';

// Next occurrence of each day (for "next Sunday", "next Monday" etc.)
const nextDays = Object.entries(dateMap).map(([d, v]) => '  next ' + d + ' = ' + v).join('\n');

return {
  ...normalized,
  customer_id: customerId,
  property_id: customerResult?.property_id || null,
  property_name: customerResult?.property_name || null,
  timezone: timezone,
  is_owner: isOwner,
  today: today,
  today_full: todayFull,
  today_year: String(yyyy),
  today_day: dayName,
  tomorrow_full: tomorrowFull,
  next_days: nextDays,
  calendar: calendar
};

// Calculate AI cost after agent execution
const normalized = $('Merge Customer ID').item.json;
const aiOutput = $input.item.json;

// GPT-4o-mini pricing (Jan 2026): $0.15/1M input, $0.60/1M output
const INPUT_COST_PER_1K = 0.00015;
const OUTPUT_COST_PER_1K = 0.0006;

// Estimate tokens (approximately 4 chars per token)
const systemPromptTokens = 800;
const messageTokens = Math.ceil((normalized.message_text || '').length / 4);
const inputTokens = systemPromptTokens + messageTokens + 200; // 200 for context

// Output is the AI response
const outputText = aiOutput.output || '';
const outputTokens = Math.ceil(outputText.length / 4);

// Calculate cost
const inputCost = (inputTokens / 1000) * INPUT_COST_PER_1K;
const outputCost = (outputTokens / 1000) * OUTPUT_COST_PER_1K;
const totalCost = inputCost + outputCost;

return {
  ...aiOutput,
  customer_id: normalized.customer_id,
  sender_id: normalized.sender_id,
  channel: normalized.channel,
  cost_calculation: {
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cost_usd: totalCost
  }
};

// V5: Extract stage and collected data from AI response
const aiOutput = $input.item.json.output || '';
const currentStage = $('Load Conversation').item.json?.conversation_stage || 'new';
const senderId = $('Normalize Input').item.json.sender_id;
const messageText = $('Normalize Input').item.json.message_text || '';

let newStage = currentStage;
let extractedData = {};

if (currentStage === 'new' || currentStage === null) {
  newStage = 'welcome_done';
}

const namePatterns = [
  /(?:i'm|im|i am|my name is|call me|this is)\s+([A-Z][a-z]+)/i,
  /^([A-Z][a-z]+)$/,
  /^([A-Z][a-z]+)\s*[!.,]?$/
];

for (const pattern of namePatterns) {
  const match = messageText.match(pattern);
  if (match && match[1] && match[1].length > 1 && match[1].length < 20) {
    extractedData.guest_name = match[1];
    if (currentStage === 'welcome_done') {
      newStage = 'name_collected';
    }
    break;
  }
}

const datePattern = /(\d{4}-\d{2}-\d{2})/g;
const foundDates = messageText.match(datePattern) || [];
if (foundDates.length >= 2) {
  extractedData.check_in_date = foundDates[0];
  extractedData.check_out_date = foundDates[1];
  if (['welcome_done', 'name_collected'].includes(currentStage)) {
    newStage = 'dates_collected';
  }
}

if (aiOutput.toLowerCase().includes('available') && currentStage === 'dates_collected') {
  newStage = 'options_shown';
}
if ((aiOutput.includes('$') || aiOutput.toLowerCase().includes('total')) && currentStage === 'options_shown') {
  newStage = 'price_revealed';
}

return {
  sender_id: senderId,
  current_stage: currentStage,
  new_stage: newStage,
  extracted_data: extractedData,
  should_update: newStage !== currentStage || Object.keys(extractedData).length > 0
};

// Prepare budget alert notification
const data = $input.item.json;

let alertType, alertEmoji, alertTitle, alertMessage;
const remaining = Number(data.remaining) || 0;

// Check from highest to lowest priority
if (data.alert_100_needed) {
  alertType = '100_percent';
  alertEmoji = '🔴';
  alertTitle = 'API Budget Exhausted';
  alertMessage = 'Your monthly API budget is exhausted. AI features will use template responses until next month.';
} else if (data.alert_80_needed) {
  alertType = '80_percent';
  alertEmoji = '🔶';
  alertTitle = 'API Budget: 80% Used';
  alertMessage = `You have used 80% of your monthly API budget. Remaining: $${remaining.toFixed(2)}. Consider reducing usage.`;
} else if (data.alert_50_needed) {
  alertType = '50_percent';
  alertEmoji = '⚠️';
  alertTitle = 'API Budget: 50% Used';
  alertMessage = `You have used 50% of your monthly API budget. Remaining: $${remaining.toFixed(2)}`;
} else {
  alertType = 'info';
  alertEmoji = 'ℹ️';
  alertTitle = 'Budget Update';
  alertMessage = `Current remaining budget: $${remaining.toFixed(2)}`;
}

return {
  alert_type: alertType,
  alert_emoji: alertEmoji,
  alert_title: alertTitle,
  alert_message: alertMessage,
  customer_id: $('Merge Customer ID').item.json.customer_id,
  remaining: remaining
};

// Budget exhausted - return template response
const normalized = $('Merge Customer ID').item.json;
const budgetInfo = $('Check Budget').item.json;

const fallbackResponses = {
  en: "I apologize, but I'm currently operating in limited mode. For immediate assistance with bookings or urgent issues, please contact our support team directly. We'll be back to full service soon!",
  es: "Disculpe, actualmente estoy operando en modo limitado. Para asistencia inmediata con reservas o problemas urgentes, contacte a nuestro equipo de soporte directamente.",
  default: "Thank you for your message. Our AI assistant is temporarily limited. Please try again later or contact support for immediate help."
};

const response = fallbackResponses.en;

return {
  output: response,
  sender_id: normalized.sender_id,
  channel: normalized.channel,
  budget_exhausted: true,
  remaining_budget: budgetInfo.remaining || 0
};

// Calculate total price for a vacation rental stay
// n8n toolCode MUST return a STRING (not an object)
try {
  const checkIn = new Date($fromAI('check_in_date', 'Check-in date in YYYY-MM-DD format'));
  const checkOut = new Date($fromAI('check_out_date', 'Check-out date in YYYY-MM-DD format'));
  const pricePerNight = parseFloat($fromAI('price_per_night', 'Price per night in USD', 'number', '100'));
  const weekendPrice = parseFloat($fromAI('weekend_price', 'Weekend price per night', 'number', String(pricePerNight)));
  const cleaningFee = parseFloat($fromAI('cleaning_fee', 'One-time cleaning fee', 'number', '0'));
  const discountPercent = parseFloat($fromAI('discount_percent', 'Discount percentage', 'number', '0'));

  const nights = Math.ceil((checkOut - checkIn) / (1000 * 60 * 60 * 24));

  if (nights <= 0 || isNaN(nights)) {
    return JSON.stringify({ error: true, message: 'Invalid dates: check-out must be after check-in' });
  }

  let weekdayNights = 0;
  let weekendNights = 0;
  for (let d = 0; d < nights; d++) {
    const day = new Date(checkIn);
    day.setDate(day.getDate() + d);
    const dow = day.getDay();
    if (dow === 5 || dow === 6) weekendNights++;
    else weekdayNights++;
  }

  const nightly = (weekdayNights * pricePerNight) + (weekendNights * weekendPrice);
  const discount = nightly * (discountPercent / 100);
  const afterDiscount = nightly - discount;
  const serviceFee = Math.round(afterDiscount * 0.12 * 100) / 100;

  let weeklyDiscount = 0;
  if (nights >= 7 && discountPercent === 0) {
    weeklyDiscount = Math.round(nightly * 0.10 * 100) / 100;
  }

  const total = Math.round((afterDiscount - weeklyDiscount + cleaningFee + serviceFee) * 100) / 100;

  return JSON.stringify({
    nights,
    weekday_nights: weekdayNights,
    weekend_nights: weekendNights,
    price_per_night: pricePerNight,
    weekend_price: weekendPrice,
    nightly_subtotal: Math.round(nightly * 100) / 100,
    custom_discount: Math.round(discount * 100) / 100,
    weekly_discount: weeklyDiscount,
    cleaning_fee: cleaningFee,
    service_fee: serviceFee,
    total: total,
    currency: 'USD',
    check_in: checkIn.toISOString().split('T')[0],
    check_out: checkOut.toISOString().split('T')[0]
  });
} catch (err) {
  return JSON.stringify({
    error: true,
    message: 'Price calculation failed: ' + err.message,
    hint: 'Calendar Manager already includes pricing. Use that instead.'
  });
}
